san_pham_kho = {
    "SP001": {"ten": "Chuột", "gia": 200000},
    "SP002": {"ten": "Bàn phím", "gia": 700000},
    "SP003": {"ten": "Màn hình", "gia": 2500000}
}

def tim_san_pham_gia_cao_nhat(danh_sach_san_pham):
    max_gia = -1
    ten_max = ""
    for sp in danh_sach_san_pham.values():
        if sp["gia"] > max_gia:
            max_gia = sp["gia"]
            ten_max = sp["ten"]
    return ten_max

