friends = {
    "An": {"Binh", "Cuong", "Dat"},
    "Binh": {"An", "Cuong", "Giang"},
    "Cuong": {"An", "Binh"}
}

def ban_chung(person1, person2, network):
    set1 = network.get(person1, set())
    set2 = network.get(person2, set())
    return set1 & set2

